b_spouse_death = observation(entity='Alice', entity_source='s30', predicate='died', predicate_source='s14')  
b_spouse_married_before = observation(entity='Bob', entity_source='s30', predicate='remarried at any time before the close of the taxable year', predicate_source='s9')  
b_joint_return_possible = observation(entity='Bob', entity_source='s30', predicate='a joint return could have been made', predicate_source='s10')  
b_child_dependent = observation(entity='Charlie', entity_source='s30', predicate='dependent of Bob under section 152(b)(2)', predicate_source='s15')  
b_child_married = observation(entity='Charlie', entity_source='s30', predicate='married at the close of the taxpayer\'s taxable year', predicate_source='s16')  
b_child_not_dependent = observation(entity='Charlie', entity_source='s30', predicate='not a dependent of Bob under section 152(b)(2)', predicate_source='s17')  
b_child_qualifying = observation(entity='Charlie', entity_source='s30', predicate='qualifying child of the individual', predicate_source='s15')  
b_child_residence = observation(entity='Charlie', entity_source='s30', predicate='maintains as his home a household which constitutes for more than one-half of such taxable year the principal place of abode', predicate_source='s14')  
b_child_residence_cost = observation(entity='Bob', entity_source='s30', predicate='furnished 40% of the costs of maintaining the home', predicate_source='s14')  
b_spouse_nonresident = observation(entity='Alice', entity_source='s30', predicate='nonresident alien', predicate_source='s24')  
b_spouse_death_year = observation(entity='Alice', entity_source='s30', predicate='died during the taxable year', predicate_source='s25')  
b_spouse_not_married = observation(entity='Bob', entity_source='s30', predicate='not married at the close of his taxable year', predicate_source='s24')  
b_spouse_not_head = observation(entity='Bob', entity_source='s30', predicate='not a head of a household', predicate_source='s27')  
b_spouse_not_alien = observation(entity='Bob', entity_source='s30', predicate='not a nonresident alien', predicate_source='s28')  
b_spouse_not_dependent = observation(entity='Charlie', entity_source='s30', predicate='not a dependent for the taxable year', predicate_source='s29')  
b_spouse_not_dependent_reason = observation(entity='Charlie', entity_source='s30', predicate='by reason of subparagraph (H) of section 152(d)(2)', predicate_source='s29')  
@scope('s0')  
def definitions_scope():  
    return True  
@scope('s1')  
def surviving_spouse_scope():  
    return definitions_scope  
@scope('s2')  
def general_surviving_spouse_scope():  
    return surviving_spouse_scope  
@scope('s4')  
def spouse_death_scope():  
    return (general_surviving_spouse_scope and b_spouse_death)  
@scope('s5')  
def dependent_child_scope():  
    return (general_surviving_spouse_scope and b_child_dependent and b_child_residence)  
@scope('s6')  
def household_cost_scope():  
    return (dependent_child_scope and b_child_residence_cost)  
@scope('s7')  
def limitations_scope():  
    return definitions_scope  
@scope('s8')  
def remarriage_limitation_scope():  
    return (limitations_scope and b_spouse_married_before)  
@scope('s9')  
def joint_return_limitation_scope():  
    return (limitations_scope and b_joint_return_possible)  
@scope('s10')  
def nonresident_limitation_scope():  
    return (limitations_scope and b_spouse_nonresident)  
@scope('s11')  
def head_of_household_scope():  
    return definitions_scope  
@scope('s12')  
def general_head_of_household_scope():  
    return head_of_household_scope  
@scope('s13')  
def head_of_household_condition_scope():  
    return (general_head_of_household_scope and b_spouse_not_married and b_spouse_not_head)  
@scope('s14')  
def household_residence_scope():  
    return (head_of_household_condition_scope and b_child_qualifying and b_child_residence)  
@scope('s15')  
def child_married_scope():  
    return (household_residence_scope and b_child_married)  
@scope('s16')  
def child_not_dependent_scope():  
    return (household_residence_scope and b_child_not_dependent)  
@scope('s17')  
def child_not_dependent_reason_scope():  
    return (household_residence_scope and b_child_not_dependent_reason)  
@scope('s18')  
def other_dependent_scope():  
    return (head_of_household_condition_scope and b_child_not_dependent)  
@scope('s19')  
def parent_residence_scope():  
    return (head_of_household_condition_scope and b_child_residence)  
@scope('s20')  
def household_cost_head_scope():  
    return (head_of_household_condition_scope and b_child_residence_cost)  
@scope('s21')  
def determination_scope():  
    return definitions_scope  
@scope('s22')  
def legal_separation_scope():  
    return (determination_scope and b_spouse_not_married)  
@scope('s23')  
def nonresident_scope():  
    return (determination_scope and b_spouse_not_married)  
@scope('s24')  
def spouse_death_scope_head():  
    return (determination_scope and b_spouse_death_year)  
@scope('s25')  
def nonresident_head_scope():  
    return (determination_scope and b_spouse_not_alien)  
@scope('s26')  
def limitations_head_scope():  
    return definitions_scope  
@scope('s27')  
def head_limitations_scope():  
    return (limitations_head_scope and b_spouse_not_alien)  
@scope('s28')  
def nonresident_head_limitation_scope():  
    return (head_limitations_scope and b_spouse_not_dependent)  
@scope('s29')  
def dependent_head_limitation_scope():  
    return (head_limitations_scope and b_spouse_not_dependent_reason)  
@rule('s14', otherwise=False)  
def household_residence_test():  
    return (household_residence_scope and (not b_child_married) and (not b_child_not_dependent))  
@rule('s15', otherwise=False)  
def child_married_test():  
    return (household_residence_scope and b_child_married)  
@rule('s16', otherwise=False)  
def child_not_dependent_test():  
    return (household_residence_scope and b_child_not_dependent)  
@rule('s17', otherwise=False)  
def child_not_dependent_reason_test():  
    return (household_residence_scope and b_child_not_dependent_reason)  
@rule('s18', otherwise=False)  
def other_dependent_test():  
    return (head_of_household_condition_scope and b_child_not_dependent)  
@rule('s19', otherwise=False)  
def parent_residence_test():  
    return (head_of_household_condition_scope and b_child_residence)  
@rule('s20', otherwise=False)  
def household_cost_head_test():  
    return (head_of_household_condition_scope and b_child_residence_cost)  
@rule('s21', otherwise=False)  
def determination_test():  
    return (determination_scope and b_spouse_not_married and b_spouse_not_head)  
@rule('s22', otherwise=False)  
def legal_separation_test():  
    return (determination_scope and b_spouse_not_married)  
@rule('s23', otherwise=False)  
def nonresident_test():  
    return (determination_scope and b_spouse_not_married)  
@rule('s24', otherwise=False)  
def spouse_death_head_test():  
    return (determination_scope and b_spouse_death_year)  
@rule('s25', otherwise=False)  
def nonresident_head_test():  
    return (determination_scope and b_spouse_not_alien)  
@rule('s26', otherwise=False)  
def limitations_head_test():  
    return (limitations_head_scope and b_spouse_not_alien)  
@rule('s27', otherwise=False)  
def head_limitations_test():  
    return (head_limitations_scope and b_spouse_not_alien)  
@rule('s28', otherwise=False)  
def nonresident_head_limitation_test():  
    return (head_limitations_scope and b_spouse_not_dependent)  
@rule('s29', otherwise=False)  
def dependent_head_limitation_test():  
    return (head_limitations_scope and b_spouse_not_dependent_reason)  
@rule('s14', otherwise=False)  
def head_of_household_definition():  
    return (head_of_household_condition_scope and (not (child_married_test or child_not_dependent_test or child_not_dependent_reason_test or other_dependent_test or parent_residence_test or household_cost_head_test)) and (not (spouse_death_head_test or nonresident_head_test or limitations_head_test or head_limitations_test or nonresident_head_limitation_test or dependent_head_limitation_test)))  
query = ('Entailment' if head_of_household_definition else 'Contradiction')
